int a = 10, b = 3;
System.out.println(a + b * 2);
System.out.println((a + b) * 2);
System.out.println(a / b + " remainder " + a % b);
System.out.println(-7 % 3);
System.out.println(10 - 4 - 3);

int n = 5;
int post = n++;   // use 5, then n becomes 6
int pre = ++n;    // n becomes 7, then use 7
System.out.println(post + " " + pre + " " + n);

int total = 10;
total += 5;       // 15
total *= 2;       // 30
total -= 4;       // 26
total /= 2;       // 13
System.out.println(total);

int age = 20;
boolean hasTicket = false;
System.out.println(age >= 18);
System.out.println(age >= 18 && hasTicket);
System.out.println(age >= 18 || hasTicket);
System.out.println(!hasTicket);
String status = age >= 18 ? "adult" : "minor";
System.out.println(status);

String typed = new String("yes");
System.out.println(typed == "yes");
System.out.println(typed.equals("yes"));
System.out.println("YES".equalsIgnoreCase(typed));

int temperature = 23;
if (temperature >= 30) {
    System.out.println("Hot");
} else if (temperature >= 20) {
    System.out.println("Warm");
} else if (temperature >= 10) {
    System.out.println("Mild");
} else {
    System.out.println("Cold");
}

String day = "SAT";
String kind = switch (day) {
    case "SAT", "SUN" -> "weekend";
    case "MON", "TUE", "WED", "THU", "FRI" -> "weekday";
    default -> "unknown";
};
System.out.println(kind);

int month = 2;
int days = switch (month) {
    case 2 -> 28;
    case 4, 6, 9, 11 -> 30;
    default -> {
        System.out.println("a long month");
        yield 31;
    }
};
System.out.println(days);

int level = 1;
switch (level) {
    case 1:
        System.out.println("one");
    case 2:
        System.out.println("two");
        break;
    case 3:
        System.out.println("three");
}
